%[text] # Object Counting with Blob Analysis
%[text] This live script loads MATLAB's built-in `coins.png` image, segments each coin as a blob, classifies the blobs by size as dimes or nickels, and computes the total value.
%[text:tableOfContents]{"heading":"Contents"}
%%
%[text] ## 1) Load and View Image
I = imread("coins.png");

imshow(I); %[output:15df80ec]
title("Built-in coins.png Image"); %[output:15df80ec]
%%
%[text] ## 2) Segment Coins from Background
%[text] The coins are brighter than the background, so automatic thresholding creates an initial binary mask. Filling holes turns each coin into a solid region, and small-object removal cleans up isolated pixels.
coinMask = imbinarize(I);
coinMask = imfill(coinMask,"holes");

imshow(coinMask) %[output:14915255]
title("Segmented Coin Mask") %[output:14915255]
%%
%[text] ## 3) Measure Coin Blobs using Image Region Analyzer
%[text] Connected-component labeling assigns one label to each coin. `regionprops` then measures the blob area, centroid, and equivalent diameter, which are the features used for counting and classification.
%[text] This can all be done in the **Image Region Analyzer App**. Explore the app, then run the code to proceed.
%[text] ![](text:image:28f9)
imageRegionAnalyzer(coinMask)
%%
%[text] **Programmatic extraction of region properties**
stats = regionprops("table",coinMask,"Centroid","EquivDiameter");

numCoins = height(stats);
diameters = stats.EquivDiameter;
centroids = stats.Centroid;
%%
%[text] ## 4) Classify Dimes and Nickels
%[text] Dimes are smaller than nickels, so the largest gap in the sorted blob diameters provides a simple data-driven threshold between the two coin sizes.
%[text] **Threshold Calculation**
histogram(diameters,15); %[output:82963f33]

xlim([46 60]) %[output:82963f33]
yticks(min(ylim):1:max(ylim)) %[output:82963f33]

diameterThreshold = 53; %[control:slider:8be9]{"position":[21,23]}
xline(diameterThreshold,'r--','LineWidth',2); %[output:82963f33]
title("Diameter Distribution and Threshold"); %[output:82963f33]
%%
%[text] **Classification**
isDime = diameters < diameterThreshold;
isNickel = diameters >= diameterThreshold;

coinType = strings(numCoins,1);
coinType(isDime) = "Dime";
coinType(isNickel) = "Nickel";
classification = table((1:numCoins)',diameters,coinType,VariableNames=["Coin","EquivalentDiameter","CoinType"]) %[output:8bbda85d]
%[text] **Visualization**
imshow(I) %[output:1d4d63b6]
viscircles(centroids(isDime,:),diameters(isDime)/2,Color="cyan",LineWidth=1); %[output:1d4d63b6]
viscircles(centroids(isNickel,:),diameters(isNickel)/2,Color="yellow",LineWidth=1); %[output:1d4d63b6]
text(centroids(:,1),centroids(:,2),coinType,Color="black",FontWeight="bold",HorizontalAlignment="center",BackgroundColor="white",Margin=1) %[output:1d4d63b6]
title("Blob Size Classification") %[output:1d4d63b6]
%%
%[text] ## 5) Count the Coins and Compute Value
%[text] The final result counts the two coin classes and converts the count into cents and dollars.
numDimes = sum(isDime);
numNickels = sum(isNickel);
totalCents = 10*numDimes + 5*numNickels;
result = table(numDimes,numNickels,totalCents,VariableNames=["Dimes","Nickels","TotalCents"]) %[output:06ac86f1]

